"use strict";
const fs = require("node:fs");
const path = require("node:path");
const cp = require("node:child_process");
const crypto = require("node:crypto");
const root = __dirname;
const source = "/Users/xu/project/worktrees/cew-fast-path";
const runner = path.join(root, "sources/optimized/docs/eval/tools/run-trial.js");
const tasks = JSON.parse(fs.readFileSync(path.join(root, "tasks.validated.json")));
if (tasks.length !== 7 || tasks.some((task) => !task.valid)) throw new Error("All seven tasks must pass preparation validation first");
const arms = ["gpt-cew", "gpt-trim", "gpt-fixed"];
const homes = { "gpt-trim": "cew-trim", "gpt-cew": "cew-home", "gpt-fixed": "cew-fixed" };
const hash = (bytes) => crypto.createHash("sha256").update(bytes).digest("hex");
const command = (args, cwd) => cp.execFileSync(args[0], args.slice(1), { cwd, encoding: "utf8" }).trim();
let plan = [];
for (let repetition = 1; repetition <= 2; repetition++) {
  for (let i = 0; i < tasks.length; i++) {
    let order = arms.map((_, k) => arms[(k + i) % arms.length]);
    if (repetition === 2) order = order.reverse();
    plan.push({ task: tasks[i].id, repetition, order });
  }
}
const criticalPlan = plan.filter((block) => block.task === "more-itertools-1247");
const remainingPlan = plan.filter((block) => block.task !== "more-itertools-1247");
plan = [...criticalPlan, ...remainingPlan];
const metadata = {
  started_at: new Date().toISOString(), candidate_sha: JSON.parse(fs.readFileSync(path.join(root, "protocol/installed-sources.json"))).find((arm) => arm.cell === "gpt-fixed").sha,
  main_sha: "e57aa53bb4b1ba8c065be5714c23e451bf6a6ad5",
  previous_candidate_sha: "00c8313e4a31f0511ced847a579d7b5342504e43",
  arms: {"gpt-cew":"main CEW", "gpt-trim":"previous PR #62 candidate00c8313 (posthocquality13/14)", "gpt-fixed":"quality-gate candidate PR #62"},
  quality_protocol_sha256: hash(fs.readFileSync(path.join(root,"protocol/frozen-quality-probes.cjs"))),
  cost_protocol_sha256: hash(fs.readFileSync(path.join(root,"cost-probes.cjs"))),
  context_protocol_sha256: hash(fs.readFileSync(path.join(root,"context-probes.cjs"))),
  promotion_protocol_sha256: hash(fs.readFileSync(path.join(root,"promotion-probes.cjs"))),
  i18n_protocol_sha256: hash(fs.readFileSync(path.join(root,"i18n-probes.cjs"))),
  usage_accounting_sha256: hash(fs.readFileSync(path.join(root,"account-usage.cjs"))),
  benchmark_driver_sha256: hash(fs.readFileSync(__filename)),
  runner_sha256: hash(fs.readFileSync(runner)), manifest_sha256: hash(fs.readFileSync(path.join(root, "tasks.validated.json"))),
  runner_usage_collector_sha256: hash(fs.readFileSync(path.join(root,"sources/optimized/docs/eval/tools/codex-usage.js"))),
  cli: command(["codex", "--version"]), node: process.version,
  model: "gpt-6.1-sol", reasoning_effort: "high", timeout_s: 720,
  concurrency: 2, trials_planned: 42, plan,
  quality_protocol_frozen_at: JSON.parse(fs.readFileSync(path.join(root, "protocol/protocol.json"))).frozen_at,
  protocol_change: "Same seven tasks, two repetitions, model prompts, strict grader, two concurrent task blocks and per-task arm rotation. Main e57 unchanged; middle control explicitly changed from10403cf topreviouscandidate00c8313 beforeallmodels. Priorcandidate13/14afterposthocmixeddtypefinding, notqualityequivalentclaim. Historiesremainseparate. Same critical-first order as f88 attempt. All42known queries (16boundary+4cost+12context+10promotion/Rounded) frozen before every model, uniform for all6critical artifacts with no model active. Both candidate outcomes must pass original suite and all42; else unstarted36 NOTRUN, incomplete. Successful gate continuesall42. Prior successful seven-task fixture validation reused unchanged with explicit provenance; per-trial baseline/target/full fresh as before.",
  isolation: "Fresh checkout, HOME, Codex state, and private virtualenv per trial; reference refs removed; same provisioned auth and model config in every arm.",
  fixture_note: tasks.find((task) => task.id === "itsdangerous-sha1").fixture_note,
};
fs.writeFileSync(path.join(root, "experiment.json"), JSON.stringify(metadata, null, 2));
fs.mkdirSync(path.join(root, "trials"), { recursive: true });
const completed = [];
function snapshot() {
  fs.writeFileSync(path.join(root, "progress.json"), JSON.stringify({ completed, count: completed.length, planned: 42, updated_at: new Date().toISOString() }, null, 2));
}
async function trial(taskId, cell, repetition) {
  const task = tasks.find((item) => item.id === taskId);
  const id = `${taskId}--${cell}--r${repetition}`;
  const dir = path.join(root, "trials", id);
  if (fs.existsSync(dir)) throw new Error(`Refusing to overwrite ${id}`);
  fs.mkdirSync(path.join(dir, "venvs"), { recursive: true });
  fs.symlinkSync(path.join(root, "repos"), path.join(dir, "repos"));
  fs.copyFileSync(path.join(root, "tasks.validated.json"), path.join(dir, "tasks.validated.json"));
  const homeName = homes[cell];
  const home = path.join(dir, "homes", homeName);
  fs.mkdirSync(path.dirname(home), { recursive: true });
  fs.cpSync(path.join(root, "templates", homeName), home, { recursive: true, verbatimSymlinks: true });
  fs.chmodSync(path.join(home, ".codex/auth.json"), 0o600);
  const originalVenv = path.join("/tmp/cew-eval/venvs", task.repo);
  const venv = path.join(dir, "venvs", task.repo);
  const copy = cp.spawnSync("cp", ["-cR", originalVenv, venv], { encoding: "utf8" });
  if (copy.status !== 0) {
    fs.rmSync(venv, { recursive: true, force: true });
    fs.cpSync(originalVenv, venv, { recursive: true, verbatimSymlinks: true });
  }
  for (const file of fs.readdirSync(path.join(venv, "bin"))) {
    const target = path.join(venv, "bin", file);
    if (!fs.lstatSync(target).isFile()) continue;
    const bytes = fs.readFileSync(target);
    if (!bytes.subarray(0, 2).equals(Buffer.from("#!"))) continue;
    const text = bytes.toString("utf8").replaceAll(originalVenv, venv);
    fs.writeFileSync(target, text);
  }
  const packagesBefore = command([path.join(venv, "bin/python"), "-m", "pip", "freeze"]);
  const runDir = path.join(dir, "runs", taskId, `${cell}-r${repetition}`);
  const env = { ...process.env, CEW_EVAL_ROOT: dir, PATH: `${venv}/bin:${process.env.PATH}`,
    VIRTUAL_ENV: venv, PYTHONPATH: `${runDir}/src:${runDir}`, PYTHONDONTWRITEBYTECODE: "1" };
  const log = fs.openSync(path.join(dir, "runner.log"), "wx");
  const startedAt = new Date().toISOString();
  const start = Date.now();
  console.log(JSON.stringify({ event: "started", task: taskId, cell, repetition, started_at: startedAt }));
  const child = cp.spawn(process.execPath, [runner, "--task", taskId, "--cell", cell, "--run", String(repetition), "--timeout", "720"],
    { cwd: source, env, stdio: ["ignore", log, log] });
  fs.closeSync(log);
  const exit = await new Promise((resolve, reject) => { child.once("error", reject); child.once("close", resolve); });
  const resultFile = path.join(dir, "results", taskId, `${cell}-r${repetition}`, "result.json");
  const result = fs.existsSync(resultFile) ? JSON.parse(fs.readFileSync(resultFile)) : null;
  const packagesAfter = command([path.join(venv, "bin/python"), "-m", "pip", "freeze"]);
  const patch = cp.execFileSync("git", ["diff", "--binary", "HEAD", "--"], { cwd: runDir, encoding: "utf8", maxBuffer: 16 * 1024 * 1024 });
  fs.writeFileSync(path.join(dir, "change.patch"), patch);
  const receipt = { task: taskId, cell, repetition, started_at: startedAt, finished_at: new Date().toISOString(),
    runner_exit: exit, total_duration_s: (Date.now() - start) / 1000, result_file: resultFile,
    packages_changed: packagesBefore !== packagesAfter, packages_before_sha256: hash(packagesBefore), packages_after_sha256: hash(packagesAfter),
    patch_sha256: hash(fs.readFileSync(path.join(dir, "change.patch"))),
    agent_log_sha256: fs.existsSync(path.join(path.dirname(resultFile), "agent.log")) ? hash(fs.readFileSync(path.join(path.dirname(resultFile), "agent.log"))) : null,
    resolved: result?.resolved ?? false, duration_s: result?.agent.duration_s ?? null, usage: result?.usage ?? null,
    raw_cli_usage: result?.raw_cli_usage ?? result?.usage ?? null,
    tests_modified: result?.tests_modified ?? null, new_failures: result?.new_failures ?? null,
    harness_error: result ? null : fs.readFileSync(path.join(dir, "runner.log"), "utf8").slice(-1500) };
  fs.writeFileSync(path.join(dir, "receipt.json"), JSON.stringify(receipt, null, 2));
  completed.push(receipt); snapshot();
  console.log(JSON.stringify({ event: "completed", count: completed.length, task: taskId, cell, repetition,
    resolved: receipt.resolved, duration_s: receipt.duration_s, usage: receipt.usage, packages_changed: receipt.packages_changed }));
}
async function stage(blocks) {
  let next = 0;
  async function worker() {
    while (next < blocks.length) {
      const block = blocks[next++];
      for (const cell of block.order) await trial(block.task, cell, block.repetition);
    }
  }
  await Promise.all([worker(), worker()]);
}
async function run() {
  await stage(criticalPlan);
  for (const controller of ["quality-probes.cjs", "cost-probes.cjs", "context-probes.cjs", "promotion-probes.cjs"]) {
    const result = cp.spawnSync(process.execPath, [path.join(root, controller)], { cwd: root, encoding: "utf8", timeout: 120000 });
    fs.writeFileSync(path.join(root, `critical-${controller}.log`), (result.stdout || "") + (result.stderr || ""));
    if (result.error || result.status !== 0) throw new Error("Critical probe infrastructure failed: " + controller);
  }
  const quality = JSON.parse(fs.readFileSync(path.join(root, "quality-probes.json")));
  const cost = JSON.parse(fs.readFileSync(path.join(root, "cost-probes.json")));
  const context = JSON.parse(fs.readFileSync(path.join(root, "context-probes.json")));
  const promotion = JSON.parse(fs.readFileSync(path.join(root,"promotion-probes.json")));
  fs.copyFileSync(path.join(root, "quality-probes.json"), path.join(root, "critical-quality-probes.json"));
  fs.copyFileSync(path.join(root, "cost-probes.json"), path.join(root, "critical-cost-probes.json"));
  fs.copyFileSync(path.join(root, "context-probes.json"), path.join(root, "critical-context-probes.json"));
  fs.copyFileSync(path.join(root,"promotion-probes.json"),path.join(root,"critical-promotion-probes.json"));
  const qualified = (report, expectedCount) => {
    const selected = report.results.filter((row) => row.cell === "gpt-fixed");
    return selected.length === 2 && selected.every((row) => row.cases.length === expectedCount && row.cases.every((test) => test.passed));
  };
  const passed = completed.filter((r) => r.cell === "gpt-fixed").every((r) => r.resolved && !r.tests_modified)
    && qualified(quality, 16) && qualified(cost, 4) && qualified(context, 12) && qualified(promotion, 10);
  metadata.critical_gate = { checked_at: new Date().toISOString(), passed, completed_trials: completed.length,
    quality_report_sha256: hash(fs.readFileSync(path.join(root, "critical-quality-probes.json"))),
    cost_report_sha256: hash(fs.readFileSync(path.join(root, "critical-cost-probes.json"))),
    promotion_report_sha256: hash(fs.readFileSync(path.join(root,"critical-promotion-probes.json"))),
    context_report_sha256: hash(fs.readFileSync(path.join(root, "critical-context-probes.json"))),
    no_measured_model_active_during_probes: true };
  fs.writeFileSync(path.join(root, "experiment.json"), JSON.stringify(metadata, null, 2));
  console.log(JSON.stringify({ event: "critical_gate", passed, completed: completed.length, planned: 42 }));
  if (!passed) {
    metadata.status = "ABORTED_AT_PREDECLARED_CRITICAL_QUALITY_GATE";
    metadata.not_run = remainingPlan.flatMap((block) => block.order.map((cell) => ({ task: block.task, cell, repetition: block.repetition, status: "NOT RUN" })));
    metadata.finished_at = new Date().toISOString();
    fs.writeFileSync(path.join(root, "experiment.json"), JSON.stringify(metadata, null, 2));
    process.exitCode = 2;
    return;
  }
  await stage(remainingPlan);
  metadata.finished_at = new Date().toISOString();
  metadata.status = "COMPLETED_ALL_42";
  fs.writeFileSync(path.join(root, "experiment.json"), JSON.stringify(metadata, null, 2));
  console.log(JSON.stringify({ event: "finished", trials: completed.length }));
}
run().catch((error) => { console.error(error.stack); process.exitCode = 1; });

