"use strict";
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const keys = ["input_tokens", "cached_input_tokens", "output_tokens", "reasoning_output_tokens"];
const zero = () => Object.fromEntries(keys.map((key) => [key, 0]));
const plus = (a, b) => Object.fromEntries(keys.map((key) => [key, a[key] + (b[key] || 0)]));
const equal = (a, b) => keys.slice(0, 3).every((key) => a[key] === b[key]);
function accountUsage(trial, home, rawUsage, rootId) {
  const dir = path.join(trial, "homes", home, ".codex/sessions");
  const files = fs.readdirSync(dir, { recursive: true }).filter((file) => file.endsWith(".jsonl"));
  const unique = new Map();
  const sessions = files.map((file) => {
    const bytes = fs.readFileSync(path.join(dir, file));
    const events = bytes.toString("utf8").trim().split("\n").map(JSON.parse);
    const meta = events.find((e) => e.type === "session_meta")?.payload;
    if (!meta?.id) throw new Error("Missing session identity: " + file);
    const records = events.filter((e) => e.type === "token_usage_record");
    for (const event of records) {
      const { response_id: id, usage } = event.payload;
      if (!id || !usage || keys.slice(0, 3).some((key) => !Number.isSafeInteger(usage[key]) || usage[key] < 0)
        || !Number.isSafeInteger(usage.reasoning_output_tokens || 0) || (usage.reasoning_output_tokens || 0) < 0
        || usage.cached_input_tokens > usage.input_tokens) throw new Error("Invalid response accounting");
      const old = unique.get(id);
      if (old && !equal(old.usage, usage)) throw new Error("Conflicting duplicate response ID");
      if (!old) unique.set(id, { response_id: id, timestamp: event.timestamp, thread_id: event.payload.thread_id, usage });
    }
    const contexts = events.filter((e) => e.type === "turn_context");
    const commands = events.filter((e) => e.type === "event_msg" && e.payload.type === "item_completed" && e.payload.item?.type === "CommandExecution")
      .map((e) => ({ command: Array.isArray(e.payload.item.command) ? e.payload.item.command.join(" ") : e.payload.item.command,
        argv: e.payload.item.command, cwd: e.payload.item.cwd, exit_code: e.payload.item.exit_code, status: e.payload.item.status,
        output_bytes: Buffer.byteLength(e.payload.item.aggregated_output || "") }));
    const functions = events.filter((e) => e.type === "response_item" && ["function_call", "custom_tool_call"].includes(e.payload.type));
    return { thread_id: meta.id, parent_thread_id: meta.forked_from_id || meta.source?.subagent?.thread_spawn?.parent_thread_id || null,
      source: meta.source, file, sha256: crypto.createHash("sha256").update(bytes).digest("hex"),
      models: [...new Set(contexts.map((e) => e.payload.model))], efforts: [...new Set(contexts.map((e) => e.payload.effort))],
      function_names: [...new Set(functions.map((e) => e.payload.name))], commands,
      file_change_events: events.filter((e) => e.type === "event_msg" && e.payload.type === "item_completed" && /FileChange/.test(e.payload.item?.type)).length };
